<template>
  <div class="metric-contract-footer" data-test="touchless-metric-footer">
    <span v-if="dataAsOf" data-test="touchless-data-as-of">
      {{ $t('touchless_data_as_of', { timestamp: formattedDataAsOf }) }}
    </span>
    <span v-if="contractVersion" class="metric-contract-item">
      {{ $t('touchless_metric_contract', { version: contractVersion }) }}
    </span>
    <span
      v-if="population"
      class="metric-contract-item"
      data-test="touchless-population"
    >
      {{
        $t('touchless_population', {
          eligible: population.eligible,
          total: population.total,
        })
      }}
    </span>
    <span
      v-if="excludedCount > 0"
      class="metric-contract-item"
      data-test="touchless-excluded"
    >
      {{ $t('touchless_excluded', { count: excludedCount }) }}
      <q-tooltip v-if="excludedReasons.length">
        <div v-for="reason in excludedReasons" :key="reason.code">
          {{ reason.label }}: {{ reason.count }}
        </div>
      </q-tooltip>
    </span>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { MetricPopulation } from 'src/services/analytics/TouchlessService';

/**
 * Every Automation Intelligence response carries a metric envelope. Showing it
 * is not decoration: without `data_as_of` and the population block, a reader
 * cannot tell whether a rate is stale or computed over a different denominator
 * than the one they have in mind.
 */
export default defineComponent({
  name: 'MetricContractFooter',

  props: {
    dataAsOf: { type: String, default: '' },
    contractVersion: { type: String, default: '' },
    population: {
      type: Object as PropType<MetricPopulation | null>,
      default: null,
    },
  },

  computed: {
    formattedDataAsOf(): string {
      if (!this.dataAsOf) return '';
      const parsed = new Date(this.dataAsOf);
      if (Number.isNaN(parsed.getTime())) {
        // Render an unparseable stamp raw rather than hiding it.
        return this.dataAsOf;
      }
      return parsed.toLocaleString();
    },

    excludedCount(): number {
      return this.population?.excluded?.count ?? 0;
    },

    excludedReasons(): { code: string; label: string; count: number }[] {
      const byReason = this.population?.excluded?.by_reason ?? {};
      return Object.keys(byReason).map((code) => ({
        code,
        label: this.exclusionLabel(code),
        count: byReason[code],
      }));
    },
  },

  methods: {
    /**
     * Exclusion reason codes come from the backend registry and may grow. A
     * known code is translated; an unknown one renders raw rather than
     * disappearing behind a missing-key placeholder.
     */
    exclusionLabel(code: string): string {
      if (!code) return '';
      const key = `touchless_exclusion_${String(code).toLowerCase()}`;
      const translated = this.$t(key) as string;
      return translated === key ? code : translated;
    },
  },
});
</script>

