<template>
  <q-card class="dashboard-widget" flat bordered :data-test="dataTest">
    <q-card-section class="widget-header">
      <div class="row items-center no-wrap">
        <Icon :icon="icon" width="20" class="text-primary" />
        <span class="widget-title q-ml-sm">{{ title }}</span>
        <q-space />
        <q-badge
          v-if="badgeCount != null && badgeCount > 0"
          color="primary"
          :label="badgeCount"
        />
        <slot name="header-actions" />
      </div>
    </q-card-section>
    <q-separator />

    <q-card-section v-if="loading" class="widget-body">
      <div v-for="i in 3" :key="i" class="row items-center q-gutter-sm q-mb-sm">
        <q-skeleton type="circle" size="28px" />
        <div class="col">
          <q-skeleton type="text" width="80%" />
          <q-skeleton type="text" width="50%" class="q-mt-xs" />
        </div>
      </div>
    </q-card-section>

    <q-card-section
      v-else-if="error"
      class="widget-empty"
      data-test="touchless-widget-error"
    >
      <Icon icon="mdi:cloud-off-outline" width="28" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6 text-caption">
        {{ errorMessage || $t('failed_to_load') }}
      </span>
      <q-btn
        flat
        dense
        size="sm"
        :label="$t('retry')"
        icon="refresh"
        class="q-mt-xs"
        @click="$emit('retry')"
      />
    </q-card-section>

    <q-card-section v-else class="widget-body">
      <slot />
    </q-card-section>

    <q-card-actions v-if="$slots.actions" class="widget-footer">
      <slot name="actions" />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';

export default defineComponent({
  name: 'TouchlessWidgetWrapper',

  components: { Icon },

  props: {
    title: { type: String, required: true },
    icon: { type: String, required: true },
    badgeCount: { type: Number, default: null },
    loading: { type: Boolean, default: false },
    error: { type: Boolean, default: false },
    errorMessage: { type: String, default: '' },
    dataTest: { type: String, default: '' },
  },

  emits: ['retry'],
});
</script>
