/**
 * Named routes for the Touchless Intelligence pages (DOCB-14197).
 *
 * Deep links are built from these names rather than from path strings, so a
 * path change is a compile-time concern and a param can never be spliced into a
 * URL unvalidated.
 */
/**
 * The report is a tab on the Analytics Dashboard, not a route of its own, so
 * it is addressed by path rather than by route name.
 */
export const TOUCHLESS_DASHBOARD_PATH = '/analytics-dashboard';

/**
 * Where a drill-down returns to: the analytics page WITH the Touchless tab
 * selected. Returning to the bare path would drop the user on Status.
 */
export const TOUCHLESS_TAB_PATH = '/analytics-dashboard?tab=touchless';
export const TOUCHLESS_SUPPLIER_ROUTE = 'touchless-supplier-detail';
export const TOUCHLESS_TRACE_ROUTE = 'touchless-document-trace';

/** The shared document redirect page, linked from evidence lists. */
export const DOCUMENT_VIEW_ROUTE = 'document-view';
