/**
 * Display helpers for the Touchless Intelligence screens (DOCB-14197).
 *
 * One definition each, because the same two decisions were being made in four
 * places and had already drifted apart:
 *
 *  * `formatPct` existed three times, each with `?? 0`, which printed a
 *    measured "0%" for a quantity the API had explicitly said does not exist.
 *    On a queue that ranks suppliers by how badly they are doing, a supplier
 *    with no finished documents is not a 0 % supplier.
 *  * confidence banding existed twice — once numeric in the supplier table and
 *    once still string-based in IssueClusterCard, where a 0.9 score rendered
 *    as the raw text "0.9" and a null one as "null".
 */

/** The em dash the screens use wherever a value does not exist. */
export const NO_VALUE = '—';

/**
 * A percentage, or the em dash when there is none.
 *
 * Null is a statement from the API — "this quantity does not exist for this
 * row" — and must never be shown as a number.
 */
export function formatTouchlessPct(value: unknown): string {
  if (typeof value !== 'number' || !Number.isFinite(value)) return NO_VALUE;
  return `${Math.round(value * 10) / 10}%`;
}

/**
 * An expected lift, in PERCENTAGE POINTS.
 *
 * Signed and unit-suffixed on purpose: a bare "18.7 %" beside a touchless rate
 * of 42.5 % reads as a share of something, when it is what the rate would gain.
 * Lived as a private computed on IssueClusterCard until the digest needed the
 * same string; one definition, so the two cannot print the same number two
 * ways.
 */
export function formatLiftPp(value: unknown): string {
  if (typeof value !== 'number' || !Number.isFinite(value)) return NO_VALUE;
  return `+${Math.round(value * 10) / 10} pp`;
}

/**
 * Provenance, normalised. The backend sends upper-case enums; a future one may
 * send something this build has never heard of, and an unknown provenance must
 * degrade to neutral rather than be asserted as deterministic.
 */
function provenanceKey(value: unknown): string {
  return typeof value === 'string' ? value.trim().toUpperCase() : '';
}

/**
 * Quasar colour for the provenance chip.
 *
 * The three states are not a severity scale, they are three different KINDS of
 * claim, so the colours separate them rather than rank them: a rule's finding
 * is neutral-authoritative (primary), a model's guess is something to check
 * (warning), a person's confirmation is settled (positive). Anything unknown
 * gets the same grey the rest of this feature uses for "no answer".
 */
export function provenanceColor(value: unknown): string {
  switch (provenanceKey(value)) {
    case 'DETERMINISTIC':
      return 'primary';
    case 'AGENT_HYPOTHESIS':
      return 'warning';
    case 'HUMAN_CONFIRMED':
      return 'positive';
    default:
      return 'grey-7';
  }
}

/**
 * Material Icons LIGATURE name for the provenance chip — never an iconify
 * `mdi:` name, which Quasar would set as a ligature and render as fragments of
 * unrelated glyphs (see touchless-icon-names.unit.spec.ts).
 */
export function provenanceIcon(value: unknown): string {
  switch (provenanceKey(value)) {
    case 'DETERMINISTIC':
      return 'rule';
    case 'AGENT_HYPOTHESIS':
      return 'psychology';
    case 'HUMAN_CONFIRMED':
      return 'verified';
    default:
      return 'help_outline';
  }
}

/**
 * Is this cause a machine's GUESS rather than a derived finding?
 *
 * The single question the card's wording turns on: a hypothesis is labelled
 * "Suspected cause", everything else "Confirmed cause". Calling a model's
 * guess "confirmed" is the one mistake this whole feature cannot afford.
 */
export function isHypothesis(value: unknown): boolean {
  return provenanceKey(value) === 'AGENT_HYPOTHESIS';
}

export type ConfidenceBand = 'high' | 'medium' | 'low';

/**
 * The API sends a 0-1 score from the clustering job, not a label.
 *
 * `confidence = min(1, affected/5) x provenance weight`, so it is a real
 * number and the chip has to band it. The thresholds read that score the way
 * the job builds it: five or more affected documents at deterministic
 * provenance reaches 1.0 and is worth acting on; a single agent-hypothesis
 * document lands near 0.2 and is not.
 *
 * Returns null when there is no score — no cluster exists for that supplier
 * yet, which is a different thing from low confidence. Out-of-range values are
 * also null: a score outside 0-1 is not something this scale can describe, and
 * guessing a band for it would be inventing a reading.
 */
export function confidenceBand(value: unknown): ConfidenceBand | null {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  if (value < 0 || value > 1) return null;
  if (value >= 0.7) return 'high';
  if (value >= 0.4) return 'medium';
  return 'low';
}

/** Quasar colour for a confidence chip; neutral grey when unknown. */
export function confidenceColor(value: unknown): string {
  switch (confidenceBand(value)) {
    case 'high':
      return 'positive';
    case 'medium':
      return 'warning';
    case 'low':
      return 'grey-6';
    default:
      return 'grey-7';
  }
}

/**
 * Should the trace explain that a clean run does NOT restore touchless status?
 *
 * Exactly one combination on the trace screen cannot be explained from what is
 * on it: a run that completed cleanly, sitting under a "human touched" badge.
 * The note belongs there and nowhere else — repeated on the blocked run it is
 * noise, and on an untouched document there is nothing to explain.
 *
 * `completed` is the only success in the backend's run outcomes
 * (`in_progress`, `completed`, `blocked`, `error`, `superseded`), checked
 * against `module/automation_intelligence/constants.py:435`.
 *
 * Lives here rather than as a component method so the test can call the real
 * rule instead of restating it — a truth table that re-implements what it
 * checks passes even after the component stops agreeing with it.
 */
export function showsRestartStickyNote(
  humanTouched: boolean | null | undefined,
  run: { run_seq?: number | null; outcome?: string | null } | null | undefined,
): boolean {
  if (!humanTouched || !run) return false;
  if (String(run.outcome || '').toLowerCase() !== 'completed') return false;
  return typeof run.run_seq === 'number' && run.run_seq > 1;
}
